"""Printed 186–187: horizontal lines, intercepts and first three line forms."""
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_native_geometry import geometry,path,AXES,AXIS_LABELS
def graph(n,kind):
 if kind=='horizontal':
  paths=AXES+[path([(35,95),(430,95)],stroke='#be123c'),path([(200,95),(200,240)],dash=True)]
  labels=AXIS_LABELS+[(35,80,'P'),(435,95,'Q'),(210,175,'b')]
 elif kind=='intercepts':
  paths=AXES+[path([(50,65),(385,270)]),path([(80,83),(80,240)]),path([(80,240),(337,240)])]
  labels=AXIS_LABELS+[(35,60,'A'),(388,277,'B'),(325,265,'C'),(58,93,'D')]
 elif kind=='slope-intercept':
  paths=AXES+[path([(50,225),(365,65)]),path([(80,80),(325,80),(325,240),(325,210),(80,210)]),path([(80,210),(325,80)])]
  labels=AXIS_LABELS+[(63,207,'C'),(90,227,'c'),(328,72,'P'),(333,240,'M'),(330,212,'N'),(66,83,'y'),(208,263,'x'),(106,202,'θ'),(374,69,'L')]
  # C-to-P is the source line; its intercept is c.
  paths[2]=path([(55,223),(365,60)])
 elif kind=='point-slope':
  paths=AXES+[path([(35,270),(385,50)]),path([(180,179),(180,240),(330,240),(330,85),(180,85)]),path([(180,179),(330,179)],dash=True)]
  labels=AXIS_LABELS+[(158,174,'A'),(330,72,'P'),(172,263,'x₁'),(321,263,'x'),(190,206,'y₁'),(340,179,'y'),(390,48,'L')]
 else:
  paths=AXES+[path([(35,270),(385,50)]),path([(180,179),(180,240),(330,240),(330,85)]),path([(180,179),(330,179)],dash=True)]
  labels=AXIS_LABELS+[(158,174,'A'),(310,76,'B'),(172,263,'x₁'),(321,263,'x₂'),(190,206,'y₁'),(340,179,'y₂'),(390,48,'L')]
 return geometry('Figure 7.'+str(n),'Figure 7.'+str(n)+' — '+kind.replace('-',' '),paths,labels)
PAGES=[page('081_page_2.jpg',186,[heading('Example 7'),paragraph('Find the equation of straight line parallel to y-axis at a distance 5 units on the right side of y-axis.'),heading('Solution'),eq(r'\mathrm{Since},\quad x=a','i'),paragraph('As, the distance is 5 units to right side of y-axis, so, equation (i) becomes x = 5.'),heading('ii. x-axis and at a distance ‘b’ from it'),paragraph('Let PQ be a straight line parallel to x-axis at a distance ‘b’ units from it see Figure 7.11. This is very clear that all the points on the same ordinate say, ‘b’. Therefore, PQ can be considered as the locus of a point at a distance ‘b’ from x-axis and all points on the PQ satisfy the condition y = b. Therefore, the equation of a straight line is parallel to x-axis at a distance b from it e.g. y = b.'),graph(11,'horizontal'),heading('Remember'),paragraph('i. If b = 0, then the straight line coincides with the x-axis and its equation becomes y = 0.'),paragraph('ii. If PQ is parallel and below the x-axis at a distance ‘b’, then its equation is y = −b.'),heading('7.4 Standard Form of Equation of a Straight Line'),paragraph('Because of their simplicity, linear equation (line) is used in many applications to describe relationships between two variables. We shall see some of these applications in this unit. First, we need to develop some standard forms that are related to linear equations.'),heading('(i) Intercepts of a straight line'),paragraph('“If a straight line AB intersects x-axis at C and y-axis at D, then OC is called the x-intercept of AB on the x-axis and OD is called the y-intercept of AB on the y-axis.'),graph(12,'intercepts'),heading('Example 8'),paragraph('Find the x and y intercepts of a line 2x+4y+6 = 0.'),heading('Solution'),paragraph('The x-intercept of a line is obtained by putting y = 0 in a line:'),eq(r'2x+4y+6=0'),eq(r'2x+4(0)=-6\ \Rightarrow\ 2x=-6\ \Rightarrow\ x=-3'),paragraph('The y-intercept of a line is obtained by putting x = 0 in a line:'),eq(r'2x+4y+6=0'),eq(r'2(0)+4y=-6\ \Rightarrow\ 4y=-6\ \Rightarrow\ y=-\frac32'),paragraph('The general criteria are that a line in two dimensional space can be determined by specifying its slope and just one point.'),heading('(ii) Slope-Intercept Form'),paragraph('Let L be the line see Figure 7.13 develops the y-intercept c on the y-axis. The line L also makes an angle θ with the positive direction of the x-axis that develops a slope m = tan θ. Let P(x,y) be any point on the line L. Draw PM parallel to y-axis and CN parallel to x-axis that give'),graph(13,'slope-intercept'),eq(r'CN=OM=x'),eq(r'NP=MP-MN=MP-OC=y-c'),paragraph('In ΔPCN, the angle is ∠PNC = 90° and the slope of the line L is giving the slope-intercept form of the line L:'),note('Intercepts are signed coordinates: Example 8 crosses at (−3,0) and (0,−3/2), so its negative signs must be retained. Figure 7.12 illustrates a general line with positive intercepts, rather than that particular example. Slope plus one point specifies a nonvertical line; a vertical line requires its fixed x-coordinate.')]),page('082_page_1.jpg',187,[eq(r'\frac{NP}{CN}=\tan\theta\ \Rightarrow\ \frac{y-c}x=\tan\theta'),eq(r'\Rightarrow\ y-c=x\tan\theta'),eq(r'\Rightarrow\ y=x\tan\theta+c=mx+c','i'),paragraph('If the straight line L passes through the origin (0,0), then c = 0 and the equation of line L becomes y = mx. In y = mx+c, m denotes the slope and c denotes the y-intercept of the line L on the axis of y.'),heading('Example 9'),paragraph('Determine the slopes of the following lines: (a) x−y = 5. (b) 2x+3y = 6.'),heading('Solution'),paragraph('a. For the slope, solve the given line for y to obtain:'),eq(r'x-y=5\ \Rightarrow\ -y=-x+5\ \Rightarrow\ y=x-5'),paragraph('Thus, the slope of the line is the coefficient of x-term which is m = 1.'),paragraph('b. For the slope of the line, solve the given line for y to obtain:'),eq(r'2x+3y=6\ \Rightarrow\ 3y=-2x+6\ \Rightarrow\ y=-\frac23x+2'),paragraph('Thus, the slope of the line is the coefficient of x-term which is m = −2/3.'),heading('Example 10'),paragraph('Find an equation of the line with slope 4, when the y-intercept is 6.'),heading('Solution'),paragraph('Result (i) is used for the assumptions m = 4, c = 6 to obtain the required slope-intercept form of a line:'),eq(r'y=4x+6'),heading('ii. Point-Slope Form'),paragraph('If L is a line see Figure 7.14 passing through the point A(x₁,y₁) and P(x,y) is any point on a line L, then, the slope of the line L is giving the point-slope form of a line L:'),graph(14,'point-slope'),eq(r'm=\frac{y-y_1}{x-x_1}'),eq(r'y-y_1=m(x-x_1)','ii'),heading('Example 11'),paragraph('Find an equation of a line with slope 4 and passes through the point (2,4).'),heading('Solution'),paragraph('Result (ii) is used for the assumptions m = 4, A(x₁,y₁) = A(2,4), to obtain the required point-slope form of a line:'),eq(r'y-4=4(x-2)'),eq(r'-4x+y-4+8=0\ \Rightarrow\ -4x+y+4=0\ \Rightarrow\ 4x-y-4=0'),heading('iii. Two-Point Form'),paragraph('If L is a line, see Figure 7.15 passing through the two points A(x₁,y₁) and B(x₂,y₂), then the slope of the line L is:'),graph(15,'two-point'),eq(r'm=\frac{y_2-y_1}{x_2-x_1}','iii'),paragraph('If the equation of a line L through the A(x₁,y₁) with slope m is'),eq(r'y-y_1=m(x-x_1)','iv'),paragraph('then the equation of a line L through the two points A(x₁,y₁) and B(x₂,y₂) is the equation of the two-point form of a line L:'),eq(r'y-y_1=\frac{y_2-y_1}{x_2-x_1}(x-x_1)','v'),note('The quotient derivations initially require nonzero horizontal differences. After rearrangement, the point-slope equation also includes the given point itself. For distinct points with x₂ = x₁, use the vertical equation x = x₁. A division-free two-point equation valid for any two distinct points is (x₂−x₁)(y−y₁) = (y₂−y₁)(x−x₁).')])]
for p in PAGES:
 p.update(title='PLANE ANALYTIC GEOMETRY STRAIGHT LINE',visualStatus='Complete horizontal-line and standard-form source, Examples 7–11, five native diagrams',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':81 if p['page']==186 else 82,'side':'right' if p['page']==186 else 'left','reason':'Full source words/equations and Example 9 negative slope confirmed with enlarged detail'})
EXAMPLES=[]
for n,q,steps,ans,p in [
('7','Find the equation parallel to the y-axis, 5 units to its right.',['A line parallel to the y-axis is vertical.','Every point on it has the same x-coordinate a.','The y-axis has x = 0.','Moving 5 units to its right gives a = 5.','Thus the equation is x = 5; y can be any real number.','Its horizontal distance to the y-axis is |5| = 5 and its finite slope is undefined.'],'x = 5.',186),
('8','Find the x and y intercepts of 2x+4y+6 = 0.',['At the x-axis, put y = 0.','Then 2x+6 = 0, so x = −3; the crossing point is (−3,0).','At the y-axis, put x = 0.','Then 4y+6 = 0, so y = −6/4 = −3/2; the crossing point is (0,−3/2).','Check (−3,0): 2(−3)+4(0)+6 = 0.','Check (0,−3/2): 0+4(−3/2)+6 = 0.','The signed intercepts are −3 and −3/2; their distances from the origin would be 3 and 3/2.'],'x-intercept −3, y-intercept −3/2.',186),
('9','Determine the slopes of (a) x−y = 5; (b) 2x+3y = 6.',['Rewrite each line in the form y = mx+c.','(a) x−y = 5 gives −y = 5−x.','Multiply by −1: y = x−5, hence m = 1.','(b) 2x+3y = 6 gives 3y = −2x+6.','Divide by 3: y = −(2/3)x+2, hence m = −2/3.','The intercept terms −5 and 2 do not affect either slope.','Check a horizontal increase of 3: y rises by 3 in (a) and falls by 2 in (b).'],'(a) 1; (b) −2/3.',187),
('10','Find an equation with slope 4 and y-intercept 6.',['Use the slope-intercept form y = mx+c.','The given slope is m = 4.','The signed y-intercept is c = 6.','Substitute both into the form: y = 4x+6.','At x = 0 the point is (0,6), as required.','An increase of 1 in x increases y by 4, confirming the slope.'],'y = 4x+6.',187),
('11','Find an equation with slope 4 through (2,4).',['Use y−y₁ = m(x−x₁).','Set x₁ = 2, y₁ = 4 and m = 4.','The equation is y−4 = 4(x−2).','Expand: y−4 = 4x−8, giving y = 4x−4.','Move terms to one side: 4x−y−4 = 0.','Check the point: 4·2−4−4 = 0.','The coefficient of x in y = 4x−4 is 4, confirming the slope.'],'y = 4x−4, or 4x−y−4 = 0.',187)]:
 EXAMPLES.append({'num':n,'title':'Line Equation and Intercepts','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':p,'jpg':'081_page_2.jpg' if p==186 else '082_page_1.jpg','verification':'All source example words and working visually checked'}]})
